# Guías de problemas frecuentes (lo que la gente busca en Google). Texto general: confirma siempre con el manual del modelo.
def _h(t, *ps):
    return f"<h2>{t}</h2>" + "".join(f"<p>{x}</p>" for x in ps)


def _ul(l):
    return "<ul>" + "".join(f"<li>{x}</li>" for x in l) + "</ul>"


def _ol(l):
    return "<ol>" + "".join(f"<li>{x}</li>" for x in l) + "</ol>"


